class StackUnderflowError(Exception):
    pass


def _tokenize(text):
    return re.findall(r"-?\d+|\S+", text)


def evaluate(input_data):
    words = {}
    stack = []

    def pop():
        if not stack:
            raise StackUnderflowError("Insufficient number of items in stack")
        return stack.pop()

    builtins = {
        "+": lambda: stack.append(pop() + pop()),
        "-": lambda: stack.append(pop() - pop()),
        "*": lambda: stack.append(pop() * pop()),
        "/": lambda: stack.append(_div(pop(), pop())),
        "dup": lambda: stack.append(pop() ...),
    }
```

Wait, careful with the order: for `-`: the stack is [a, b], and we want a - b. pop() returns b, then a. So `stack.append(pop() - pop())` → b - a. Wrong. Correct is: `b = pop(); a = pop(); stack.append(a - b)`.

